type MemqlClientMessage_RotateAuth struct {
	// RotateAuth -- swap the bearer token on a live stream without
	// tearing it down. Long-lived stream clients (memql-cockpit
	// most notably) call this from their background token-refresh
	// path so admin-side revocation / access changes propagate to
	// an in-flight session in O(seconds) rather than O(stream
	// lifetime). The server re-verifies the presented token, reloads
	// the partition ACL, and swaps streamSession.identity + .access
	// atomically. See handleRotateAuth.
	RotateAuth *RotateAuthMsg `protobuf:"bytes,71,opt,name=rotate_auth,json=rotateAuth,proto3,oneof"`
}

